import { stdout } from std.io;
class P {
    n: Int32;
    construct(n: Int32) { this.n = n; }
    _equals(other: P): Boolean { return this.n == other.n; }
}
fn main(): Void {
    mut a = P(3);
    mut b = P(3);
    mut c = a;
    stdout.println(a == b);
    stdout.println(a is b);
    stdout.println(a is c);
    stdout.println(a != P(4));
}
